// Generate a sample task (simulating AI generation)
const taskTemplates = [
  {
    title: "Build a REST API with Express.js",
    description: "Create a simple REST API using Node.js and Express. Include endpoints for CRUD operations on a resource of your choice. Implement proper error handling and input validation.",
    difficulty_level: "intermediate",
    category: "Backend Development",
    estimated_duration: 120,
    learning_objectives: ["Learn Express.js framework", "Understand REST principles", "Practice API design"]
  },
  {
    title: "Create a React Component Library",
    description: "Build a reusable component library using React and TypeScript. Create at least 5 components (Button, Input, Modal, Card, Form) with proper TypeScript interfaces and styling.",
    difficulty_level: "intermediate",
    category: "Frontend Development",
    estimated_duration: 90,
    learning_objectives: ["Master React components", "Learn TypeScript", "Practice component design"]
  },
  {
    title: "Database Design Challenge",
    description: "Design a normalized database schema for an e-commerce platform. Create ERD diagrams and implement the schema in PostgreSQL with proper relationships and constraints.",
    difficulty_level: "advanced",
    category: "Database",
    estimated_duration: 150,
    learning_objectives: ["Learn database normalization", "Practice ERD design", "Understand SQL relationships"]
  }
];

// Select a random task template
const randomIndex = Math.floor(Math.random() * taskTemplates.length);
const selectedTask = taskTemplates[randomIndex];

// Add metadata
return {
  json: {
    ...selectedTask,
    generated_by_ai: true,
    created_at: new Date().toISOString()
  }
};

// Create summary of the automation run
const taskData = $input.first().json;
const summary = {
  message: `✅ Task Generation Complete!

📋 New Task Created:
- Title: ${taskData.title}
- Category: ${taskData.category}
- Difficulty: ${taskData.difficulty_level}
- Duration: ${taskData.estimated_duration} minutes

🎯 Assigned to Spring 2024 cohort students
📊 Stored in PostgreSQL
🤖 Generated by AI Simulation
⏰ Triggered at 6:00 AM daily

Timestamp: ${new Date().toLocaleString()}`,
  task_id: taskData.id,
  timestamp: new Date().toISOString()
};

return { json: summary };
